import { FalkorDB } from 'falkordb';

const db = await FalkorDB.connect({
  username: process.env.FALKOR_USER,
  password: process.env.FALKOR_PASS,
  socket: { host: 'localhost', port: 6379 }
});

const graph = db.selectGraph('memory');
await graph.query(`CREATE (:Rider {name:'Valentino Rossi'})-[:rides]->(:Team {name:'Yamaha'})`);

const res = await graph.query(
  `MATCH (r:Rider)-[:rides]->(t:Team) WHERE t.name = $name RETURN r.name`,
  { params: { name: 'Yamaha' } }
);

await db.close();

