// Entity nodes carry TWO labels: the type + __Entity__.  id = "name__type" (e.g. "alice__person")
// Default 11 types: Person, Organization, Technology, Product, Location, Date, Event,
//                   Concept, Law, Dataset, Method   (low-confidence NER -> label `Unknown`)
// Edges:
//   (:Document)-[:PART_OF]->(:Chunk)          (:Chunk)-[:NEXT_CHUNK]->(:Chunk)
//   (:__Entity__)-[:MENTIONED_IN]->(:Chunk)
//   (:__Entity__)-[:RELATES]->(:__Entity__)   <-- the ONLY knowledge edge type
// RELATES props: rel_type, fact, description, keywords, weight, src_name, tgt_name,
//                source_chunk_ids, spans, embedding
// NOTE: README says "MENTIONS" edges. That is WRONG. The real edge is MENTIONED_IN.

// 3-hop with provenance back to source text — the money query for judges
MATCH p = (a:Person {name:$name})-[r1:RELATES]->(x)-[r2:RELATES]->(y)-[r3:RELATES]->(z)
WHERE r1.weight >= 0.5
WITH a, z, [rel IN relationships(p) | rel.fact] AS chain
MATCH (z)-[:MENTIONED_IN]->(c:Chunk)<-[:PART_OF]-(d:Document)
RETURN a.name, z.name, chain, c.text, d.path
LIMIT 10;

// Filter by the original relation type (it lives in a property, not the edge label)
MATCH (a:Person)-[r:RELATES {rel_type:"WORKS_AT"}]->(b:Organization) RETURN a.name, b.name;

import { Laser, jsonCodec } from "@laserdata/laser-sdk"

interface Order {
  readonly id: number
  readonly total: number
}

const ORDER_CODEC = jsonCodec<Order>((value) => {
  if (typeof value !== "object" || value === null) {
    throw new TypeError("order must be an object")
  }
  const { id, total } = value as Record<string, unknown>
  if (typeof id !== "number" || typeof total !== "number") {
    throw new TypeError("order fields are invalid")
  }
  return { id, total }
})

await using laser = await Laser.connectEnv()   // reads LASER_CONNECTION_STRING
const topic = laser.stream("shop").topic("orders")
await topic.ensure(2)
await topic.publish().json({ id: 1, total: 99 }).send()

const records = await topic.json(ORDER_CODEC).records("log-reader")
for (const result of await records.poll()) {
  if (result.kind === "record") {
    console.log(result.record.value.total)
  }
}

falkordb.query        cypher (required, use $name placeholders), params (object), graph (optional)
                      -> { columns, rows, row_count, truncated, stats? }
falkordb.list_graphs  no params -> { graphs }
falkordb.get_schema   graph (optional) -> { labels, relationship_types, property_keys }

Read-only by DEFAULT: queries run through GRAPH.RO_QUERY, so FalkorDB itself rejects
CREATE/MERGE/SET/DELETE server-side. Set allow_writes=true for the write path.
Values always travel as Cypher parameters, never interpolated into query text.

// ---- package.json of the ORCHESTRATOR agent ----
// {
//   "dependencies": {
//     "@guildai/agents-sdk": "*",
//     "@guildai/<owner>~memory-agent": "^1.0.0",   // published specialist #1
//     "@guildai/<owner>~action-agent": "^1.0.0"    // published specialist #2
//   }
// }

'use agent';

import { agent, type Task, userInterfaceTools } from '@guildai/agents-sdk';
import memoryAgentTool from '@guildai/<owner>~memory-agent/tool';
import actionAgentTool from '@guildai/<owner>~action-agent/tool';
import { z } from 'zod';

const tools = {
  memory: memoryAgentTool,   // handoff target 1 (FalkorDB graph recall)
  actor:  actionAgentTool,   // handoff target 2 (RocketRide execution)
  ...userInterfaceTools,     // ui_prompt / ui_notify => human-in-the-loop
};
type Tools = typeof tools;

const inputSchema = z.object({ event: z.string() });   // MUST be z.object() at root
const outputSchema = z.object({ decision: z.string(), executed: z.boolean() });
type Input = z.infer<typeof inputSchema>;
type Output = z.infer<typeof outputSchema>;

async function run(input: Input, task: Task<Tools>): Promise<Output> {
  // 1. HANDOFF #1 — delegate to the memory specialist. Typed via its own schemas.
  const recall = await task.tools.memory({ type: 'text', text: input.event });

  // 2. HUMAN-IN-THE-LOOP — blocking approval gate
  const approval = await task.tools.ui_prompt({
    type: 'text',
    text: `Graph memory says: ${recall.text}\nExecute the action? (yes/no)`,
  });
  if (!/^y/i.test(approval.text)) return { decision: recall.text, executed: false };

  // 3. HANDOFF #2 — delegate execution to the action specialist
  await task.tools.actor({ type: 'text', text: `ACT ON: ${recall.text}` });
  return { decision: recall.text, executed: true };
}

export default agent({ description: 'Orchestrates memory + action specialists', inputSchema, outputSchema, tools, run });

// task.gather ONLY accepts tool-call expressions (task.tools.X(...), sub-agent tool calls,
// hook tools). The ToolCallPromise brand REJECTS arbitrary promises (fetch, timers) at compile
// time — this is exactly why Promise.all does not work in the compiled agent body.
const [nowData, everData] = await task.gather([
  task.tools.laserdata_stream_tail({ topic: 'events' }),   // real-time layer
  task.tools.memory({ type: 'text', text: input.event }),  // sub-agent handoff, in parallel
]);

// Fail-soft variant:
const results = await task.gatherSettled([ /* ... */ ]);
for (const r of results) {
  if (r.status === 'fulfilled') task.console.info(String(r.value));
  else task.console.warn(`failed: ${r.reason}`);
}

