import { llmAgent, guildTools, userInterfaceTools, pick } from '@guildai/agents-sdk';

export default llmAgent({
  description: 'Coordinates the memory and action specialists in this workspace',
  tools: { ...pick(guildTools, ['guild_get_me']), ...userInterfaceTools },
  systemPrompt: `You coordinate specialists. First delegate recall to the memory agent,
    then ask the human to approve via ui_prompt, then delegate execution to the action agent.`,
  useWorkspaceAgents: true,   // <- the switch that enables dynamic agent-to-agent calls
