# Maps MCP tool name -> (method, path_template, payload_builder, queueable_verb)
_VERB_DISPATCH: dict[str, tuple[str, str, "Callable[[dict], dict]", str | None]] = {
    "unblock_remember": ("POST", "/v1/remember", _passthrough, None),
    "unblock_query":    ("POST", "/v1/query",    _passthrough, None),
    "unblock_get":      ("GET",  "/v1/blocks/{block_id}", _strip_keys("block_id"), None),
    "unblock_relate":   ("POST", "/v1/relate",   _passthrough, None),
    "unblock_ingest":   ("POST", "/v1/ingest",   _build_ingest_payload, "ingest"),
}

def _passthrough(args: dict) -> dict:
    return dict(args)

def _strip_keys(*keys: str):
    def builder(args: dict) -> dict:
        return {k: v for k, v in args.items() if k not in keys}
    return builder

entry = _VERB_DISPATCH.get(target) or GENERATED_DISPATCH.get(target)
if entry is None:
    return [TextContent(type="text", text=json.dumps({"error": f"unknown tool: {target}"}))]
method, path_template, builder, queueable_verb = entry
# Substitute path params from arguments BEFORE the builder strips them.
try:
    path = path_template.format(**arguments)
except KeyError as e:
    return [TextContent(type="text",
        text=json.dumps({"error": f"missing required path param: {e!s}"}))]
payload = builder(arguments)
if method.upper() in {"GET", "DELETE"}:
    params = {k: v for k, v in payload.items() if v is not None}
    return await _catalog_request(method, path, params=params or None,
                                 queueable_verb=queueable_verb, target_verb=target)
return await _catalog_request(method, path, payload=payload,
                             queueable_verb=queueable_verb, target_verb=target)

def _current_persona_name(ctx: "AgentContext | None") -> str | None:
    """The persona selector THIS session declared, or None.
    stdio (ctx is None): one process = one session -> the stdio key.
    HTTP: keyed STRICTLY on the request's Mcp-Session-Id (ctx.session_id) so
    concurrent sessions on one device key stay isolated. A missing/empty
    session_id has NO safe per-session discriminator on a shared pod, so we
    return None — we must NEVER collapse it onto the shared stdio bucket,
    which would bleed one sessionless request's persona into another's."""
    if ctx is None:
        return session_persona.bound_with_durable_fallback(None, grant_did=None, is_stdio=True)
    if ctx.request_persona_selector:      # explicit per-request header wins
        return ctx.request_persona_selector
    return session_persona.bound_with_durable_fallback(
        ctx.session_id, grant_did=durable_grant_key(ctx))

// 1) "What do we know about X, and what contradicts it?" — 2 hops, impossible in the SQL model
//    without a recursive CTE over a table that has no relation column.
MATCH (n:Entity {name: $entity})<-[:MENTIONS]-(b:Block)
OPTIONAL MATCH (b)-[r:RELATES {relation:'contradicts'}]-(c:Block)
RETURN b.block_id, b.content, b.block_type,
       collect({id:c.block_id, content:c.content}) AS contradicted_by
ORDER BY b.created_at DESC LIMIT 20;

// 2) Supersede-lineage resolution: give me the CURRENT truth, not the stale version.
MATCH p = (old:Block {block_id:$id})<-[:RELATES* {relation:'supersedes'}]-(newest:Block)
WHERE NOT (newest)<-[:RELATES {relation:'supersedes'}]-()
RETURN newest.block_id, newest.content, length(p) AS revisions;

// 3) Cross-agent provenance: which agent's memories are load-bearing for this decision?
MATCH (d:Block {block_type:'decision'})-[:RELATES* 1..3]->(evidence:Block)<-[:AUTHORED]-(a:Agent)
RETURN a.did, a.name, count(DISTINCT evidence) AS supporting_memories
ORDER BY supporting_memories DESC;

// 4) Hybrid: vector recall + graph expansion in ONE query (the FalkorDB flex).
CALL db.idx.vector.queryNodes('Block','embedding', 10, vecf32($qvec)) YIELD node AS seed
MATCH (seed)-[:MENTIONS]->(e:Entity)<-[:MENTIONS]-(neighbor:Block)
WHERE neighbor <> seed
RETURN seed.block_id, e.name, collect(neighbor.block_id)[..5] AS expanded;

// CROSS-RUNTIME CONTRACT — TS client and Python persona emit byte-identical envelopes.
// { kind: "say"|"dm"|"ask"|"reply"|"townhall", source: <agentId>, ts: <epoch_ms>, ...extra }
//   say:      extra = { msg }
//   dm:       extra = { to, msg }
//   ask:      extra = { question_id, msg, options }
//   reply:    extra = { question_id, msg }
//   townhall: extra = { to, msg }        // DIRECTED fan-out, never a firehose publish

export interface ChatEvent {
  readonly kind: ChatEventKind;
  readonly source: string;
  readonly ts: number;
  readonly msg?: string;
  readonly to?: string;
  readonly question_id?: string;
  readonly options?: readonly string[];
  readonly source_proven?: boolean;   // <- attestation: is `source` PROVEN or merely asserted?
}

// ask()/reply() correlation contract (client.ts:872-1030) — maps 1:1 to a Guild human-in-loop step
export interface AskOpts   { options?: readonly string[]; timeoutSec?: number; default?: string; questionId?: string }
export interface AskResult { answer: string|null; timedOut: boolean; questionId: string;
                             event: ChatEvent|null; responder: string|null; responder_proven: boolean }

